Here are a few quick start examples to get you going with the finance-yahoo API:

```typescript
// Get stock quote data for a specific symbol (e.g., AAPL)
async function getStockQuote(symbol: string) {
  try {
    const quoteData = await client.getV7FinanceQuote({ symbols: symbol });
    console.log(`Quote data for ${symbol}:`, quoteData);
    return quoteData;
  } catch (error) {
    console.error("Error fetching quote data:", error);
    return null;
  }
}

getStockQuote("AAPL");
```

```typescript
// Query data using YQL to get historical stock prices
async function getHistoricalData(symbol: string, startDate: string, endDate: string) {
  const yqlQuery = `select * from yahoo.finance.historicaldata where symbol = "${symbol}" and startDate = "${startDate}" and endDate = "${endDate}"`;
  try {
    const historicalData = await client.postV2PublicYql({ q: yqlQuery, format: 'json', env: 'store://datatables.org/alltableswithkeys' });
    console.log(`Historical data for ${symbol}:`, historicalData);
    return historicalData;
  } catch (error) {
    console.error("Error fetching historical data:", error);
    return null;
  }
}

getHistoricalData("MSFT", "2023-01-01", "2023-01-31");
```

